import torch
import torch.nn as nn
import math
from torch.utils.cpp_extension import load_inline

conv1d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv1d_kernel(
    const float* input, const float* weight, const float* bias,
    float* output,
    int batch_size, int in_channels, int out_channels,
    int input_len, int kernel_size, int stride, int dilation,
    int output_len
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= batch_size * out_channels * output_len) return;

    int b = idx / (out_channels * output_len);
    int oc = (idx % (out_channels * output_len)) / output_len;
    int op = idx % output_len;

    float val = 0.0f;

    for (int ic = 0; ic < in_channels; ++ic) {
        for (int k = 0; k < kernel_size; ++k) {
            int ip = op * stride + k * dilation;
            if (ip < 0 || ip >= input_len) continue;

            float x = input[b * in_channels * input_len + ic * input_len + ip];
            float w = weight[oc * in_channels * kernel_size + ic * kernel_size + k];
            val += x * w;
        }
    }

    if (bias) val += bias[oc];
    output[idx] = val;
}

torch::Tensor conv1d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int stride,
    int dilation
) {
    TORCH_CHECK(input.dim() == 3, "Input must be 3D");
    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int input_len = input.size(2);

    int out_channels = weight.size(0);
    int kernel_size = weight.size(2);

    int output_len = (input_len - dilation * (kernel_size - 1) - 1) / stride + 1;
    auto output = torch::zeros({batch_size, out_channels, output_len}, input.options());

    int num_elements = batch_size * out_channels * output_len;
    int threads = 256;
    int blocks = (num_elements + threads - 1) / threads;

    conv1d_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias ? bias->data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        batch_size, in_channels, out_channels,
        input_len, kernel_size, stride, dilation,
        output_len
    );

    return output;
}
"""

conv1d_cpp = "torch::Tensor conv1d_forward(torch::Tensor, torch::Tensor, c10::optional<torch::Tensor>, int, int);"

conv1d_ext = load_inline(
    name="conv1d_ext",
    cpp_sources=conv1d_cpp,
    cuda_sources=conv1d_source,
    functions=["conv1d_forward"],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, 
                 stride: int = 1, dilation: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.dilation = dilation

        self.weight = nn.Parameter(torch.empty(out_channels, in_channels, kernel_size))
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter('bias', None)

        self.reset_parameters()

    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1 / math.sqrt(fan_in)
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return conv1d_ext.conv1d_forward(
            x, 
            self.weight, 
            self.bias if self.bias is not None else None,
            self.stride,
            self.dilation
        )
